-typedef struct __CMS_NET_HANDEL__
-{
-    int             type;
-    struct sockaddr to_addr;
-    int             fd;
-} CMS_NET_HANDEL;
-
-void *cms_connect(const char *url, const char *port, enum CMS_TRANS_PROT_TYPE type)
-{
-    int              fd = -1;
-    struct addrinfo *addr_list;
-    struct addrinfo *addr;
-    struct addrinfo  addr_info;
-    struct sockaddr  to_addr;
-
-	cms_memset(&addr_info, 0, sizeof(addr_info));
-    if (CMS_TCP == type)
-    {
-        addr_info.ai_protocol = IPPROTO_TCP;
-        addr_info.ai_socktype = SOCK_STREAM;
-    }
-    else if (CMS_UDP == type)
-    {
-        addr_info.ai_protocol = IPPROTO_UDP;
-        addr_info.ai_socktype = SOCK_DGRAM;
-    }
-    else
-        return NULL;
-
-    if (getaddrinfo(url, port, &addr_info, &addr_list))
-    {
-        return NULL;
-    }
-
-    for (addr = addr_list; addr != NULL; addr = addr->ai_next)
-    {
-        fd = socket(addr->ai_family, addr->ai_socktype, addr->ai_protocol);
-        if (fd < 0)
-        {
-            continue;
-        }
-
-        if (type == CMS_UDP)
-        {
-            to_addr = *(addr->ai_addr);
-            break;
-        }
-
-        if (type == CMS_TCP && connect(fd, addr->ai_addr, addr->ai_addrlen) == 0)
-        {
-            break;
-        }
-        closesocket(fd);
-        fd = -1;
-    }
-    freeaddrinfo(addr_list);
-    if (fd < 0)
-        return NULL;
-    CMS_NET_HANDEL *handle = cms_malloc(sizeof(CMS_NET_HANDEL));
-    if (handle == NULL)
-        return NULL;
-    handle->type    = type;
-    handle->to_addr = to_addr;
-    handle->fd      = fd;
-    return (void *)handle;
-}
-
-static int cms_tcp_send(int fd, const void *data, size_t size, int timeout_ms)
-{
-    if (timeout_ms)
-    {
-        struct timeval interval = {timeout_ms / 1000, (timeout_ms % 1000) * 1000};
-        setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, (char *)&interval, sizeof(struct timeval));
-    }
-    return send(fd, data, size, 0);
-}
-
-static int cms_udp_send(int fd, const void *data, size_t size, int timeout_ms, const struct sockaddr *to, size_t tolen)
-{
-    if (timeout_ms)
-    {
-        struct timeval interval = {timeout_ms / 1000, (timeout_ms % 1000) * 1000};
-        setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, (char *)&interval, sizeof(struct timeval));
-    }
-    return sendto(fd, data, size, 0, to, tolen);
-}
-
-static int cms_tcp_recv(int fd, void *data, size_t size, int timeout_ms)
-{
-    int            rc;
-    struct timeval interval;
-    fd_set         read_fds;
-
-    FD_ZERO(&read_fds);
-    FD_SET(fd, &read_fds);
-
-    interval.tv_sec  = timeout_ms / 1000;
-    interval.tv_usec = (timeout_ms % 1000) * 1000 + 1;
-
-    rc = select(fd + 1, &read_fds, NULL, NULL, &interval);
-    if (rc <= 0)
-        return rc;
-
-    rc = recv(fd, data, size, 0);
-    if (rc == 0)
-    {
-        closesocket(fd);
-        return -1;
-    }
-    return rc;
-}
-
-static int cms_udp_recv(int fd, void *data, size_t size, int timeout_ms, struct sockaddr *from, uint32_t *fromlen)
-{
-    int            rc;
-    struct timeval interval;
-    fd_set         read_fds;
-
-    FD_ZERO(&read_fds);
-    FD_SET(fd, &read_fds);
-
-    interval.tv_sec  = timeout_ms / 1000;
-    interval.tv_usec = (timeout_ms % 1000) * 1000 + 1;
-
-    rc = select(fd + 1, &read_fds, NULL, NULL, &interval);
-    if (rc <= 0)
-    {
-        return rc;
-    }
-    return recvfrom(fd, data, size, 0, from, fromlen);
-}
-
-int cms_send_with_timeout(void *net_handle, const void *data, size_t size, int timeout_ms)
-{
-    CMS_NET_HANDEL *handle = (CMS_NET_HANDEL *)net_handle;
-    if (handle == NULL)
-        return -1;
-    if (handle->type == CMS_TCP)
-    {
-        return cms_tcp_send(handle->fd, data, size, timeout_ms);
-    }
-    else
-    {
-        return cms_udp_send(handle->fd, data, size, timeout_ms, &(handle->to_addr), sizeof(handle->to_addr));
-    }
-}
-
-int cms_recv_with_timeout(void *net_handle, void *mem, size_t len, int timeout_ms)
-{
-    CMS_NET_HANDEL *handle = (CMS_NET_HANDEL *)net_handle;
-    if (handle == NULL)
-        return -1;
-    if (handle->type == CMS_TCP)
-    {
-        return cms_tcp_recv(handle->fd, mem, len, timeout_ms);
-    }
-    else
-    {
-        uint32_t fromlen = sizeof(handle->to_addr);
-        return cms_udp_recv(handle->fd, mem, len, timeout_ms, &(handle->to_addr), &fromlen);
-    }
-}
-
-int cms_closesocket(void *net_handle)
-{
-    CMS_NET_HANDEL *handle = (CMS_NET_HANDEL *)net_handle;
-    if (handle == NULL)
-        return -1;
-    int rc = closesocket(handle->fd);
-    cms_free(handle);
-    return rc;
-}

